155	// sandboxEnvBlock returns the text of the `env -i ... "$@")` assignment block
156	// inside the script's sandbox() helper. Scoping the assertion to that block is
157	// the point: the same three strings appearing in a comment, or exported for
158	// one command only, would not protect the other children.
159	func sandboxEnvBlock(script string) (string, error) {
160		const marker = "sandbox() {"
161		start := strings.Index(script, marker)
162		if start < 0 {
163			return "", errNoSandboxHelper
164		}
165		rest := script[start:]
166		envAt := strings.Index(rest, "env -i")
167		if envAt < 0 {
168			return "", errNoSandboxEnv
169		}
170		rest = rest[envAt:]
171		end := strings.Index(rest, `"$@")`)
172		if end < 0 {
173			return "", errNoSandboxEnvEnd
174		}
175		return rest[:end], nil
176	}
