}

func referenceBoundedSingleRepoRetrievalText(query string, results []unifiedResult, extras retrievalTransportExtras) ([]byte, error) {
	extras = cloneRetrievalTransportExtras(extras)
	count := len(results)
	anythingTruncated := false
